import math

def expected_questions(n, strings):
    if n == 1:
        return 1.0 / len(strings[0])
    probabilities = []
    for i, string in enumerate(strings):
        position = 0
        while len(set([string[pos] for pos in range(len(string))])) < len(strings):
            if len(strings) == 1:
                probabilities.append(math.log(1 / len(strings[0])))
                break
            probabilities.append(math.log(len(strings) / len(strings.select([strings[i] for strings in strings])))
            position += 1
        else:
            probabilities.append(0)
        strings.pop(i)
    return sum(probabilities) / len(probabilities)

