def detectCyclePercolate(graph: List[List[int]], start: int) -> bool:
    visited = [False] * (n + 1)
    path = []
    didCycle = False

    def explore(node):
        nonlocal didCycle
        visited[node] = True
        path.append(node)

        for neighbor in graph[node]:
            if not visited[neighbor]:
                if explore(neighbor):
                    didCycle = True
                    return
            else:
                if neighbor in path:
                    if len(path) > 1 and path[-1] in path[:-1]:
                        didCycle = True
                    break

        path.pop()
        return didCycle

    for node in range(1, n + 1):
        if not visited[node]:
            explore(node)

    return didCycle

def buildNewGraph(edges: List[List[int]]) -> List[List[int]]:
    graph = [[] for _ in range(n + 1)]

    for u, v in edges:
        if detectCyclePercolate(graph, u) and detectCyclePercolate(graph, v):
            return [-1]
        graph[u].append(v)
        graph[v].append(u)

    return graph

