from collections import defaultdict

def find(n, skills):
    ancestors = [0] * n
    temp = [-1] * n
    k = 0
    for i in range(n*n, 4*n, 4):
        ancestors[i-1] = i//2
        if ancestors[i//2] != -1:
            temp[i//2] += temp[i]
    for i in range(1, n):
        while i != ancestors[i]:
            k += temp[ancestors[i-1]]
            ancestors[i] = temp[ancestors[i]]
        k += temp[i]
        temp[i] = k
    return len(set((i, temp[i//2]) for i in skills)), temp

def solve(n, skills, changes):
    nums, pref = [0], {0: 1}
    for change in range(len(changes)):
        new_difficulty = []
        for i in skills:
            if (i, change + 1) in pref:
                new_difficulty.append(pref[(i, change + 1)])
        pref[change] = pref[change - 1] + min(new_difficulty)
        nums.append(pref[change] + pref[change - 1])
    return len(nums) // 2 - nums.count(0)

