MOD = 998244353

def factorial_mod(n, mod):
    """Calculate factorial of n modulo mod"""
    fact = 1
    for i in range(1, n+1):
        fact = (fact * i) % mod
    return fact

def inverse_mod(n, mod):
    """Calculate the modular inverse of n modulo mod"""
    return pow(n, mod-2, mod)

def combinations(n, k, mod):
    """Calculate the binomial coefficient C(n, k) modulo mod"""
    if k == 0:
        return 1
    return (factorial_mod(n, mod) * inverse_mod(factorial_mod(k, mod), mod)) % mod * inverse_mod(factorial_mod(n-k, mod), mod) % mod

def main():
    n, x = map(int, input().split())
    if x < n:
        print(2 * combinations(n-1, x-1, MOD))
    else:
        print(combinations(n-1, n-2, MOD))

