            if coins + cashier_dissatisfaction[next_day - day - 1] * sum(coins_diff) >= daily_expenditure[next_day - day - 1]:
                cost = coins_diff[0] * note + sum(coins_diff[1:]) if note else sum(coins_diff)
                remaining_expenditure = daily_expenditure[next_day - day - 1] - coins + cashier_dissatisfaction[next_day - day - 1] * sum(coins_diff)
                result = min(result, self_expenditure[next_day][1] + remaining_expenditure * note + cost + dfs(next_day, coins + cashier_dissatisfaction[next_day - day - 1] * sum(coins_diff), residue, note + 1, coins_diff + [1]))
        return result

    # Initialize the self-expenditure matrix with zeros
    for _ in range(n):
        for expense in daily_expenditure:
            self_expenditure[-1].append(expenditure)

    memo = {}
    moves = []

    # Calculate the minimum cashier dissatisfaction and corresponding moves for each day
    for day in reversed(range(n)):
        coins = sum(m[i] for i in range(day, n))
        cost = 0 if coins > 0 else 0
        moves.append([day, coins + cashier_dissatisfaction[day], coins, 0, []])

    for _ in range(m):
        memo.clear()
        moves.append([n, 0, 0, -1, [1] * (n + 1)])

    for move in moves:
        if move[4] and memo.get((move[0], move[1])) is None:
            cost = memo[move[0], move[1]] = move[3] + move[1] * cashier_dissatisfaction[move[0]] + dfs(move[0], 0, 0, move[2], move[4])

    return cost, sum(move[:-1][2] for move in moves if move[-1] == -1)

