from collections import defaultdict

def count_balanced_combinations(n, k, skills, adjustments):
    balanced_count = 0
    skill_set = set()

    for adjustment in adjustments:
        a, b = adjustment
        a_count = 0  # Count of skill_level > a
        b_count = 0  # Count of skill_level > b

        # Count of skill levels > a for each skill level in set
        for skill in sorted(skill_set):
            if skill <= a:
                a_count += 1
            else:
                break

        # Count of skill levels > b for each skill level in set
        for skill in sorted(skill_set):
            if skill <= b:
                b_count += 1
            else:
                break

        # Check if all skill levels in the range (a, b) are balanced
        if all(b_count >= 0 and a_count >= 0 and a_count <= b_count for a, b in skill_set):
            balanced_count += 1

        # Update skill_set for new adjustment
        for skill in range(a, b+1):
            skill_set.discard(skill)
            if a != b:
                skill_set.add(skill)

    # Each balanced set can be permuted in 3! ways
    balanced_count *= 3 * 2 * 1

    return balanced_count
