from collections import defaultdict

def construct_new_graph(n, m, edges):
    G = defaultdict(set)

    for u, v in edges:
        G[u].add(v)
        G[v].add(u)

    edges_used = defaultdict(set)
    for u, v in edges:
        if u == v: continue
        edges_used[u].add((v, u))
        edges_used[v].add((u, v))

    new_edges = []

    for u, v in edges:
        new_edges.append(str(u) + ' ' + str(v))

    new_edges = sorted(new_edges, key=lambda x: int(x.split(' ')[0]))

    for u in range(1, n + 1):
        if len(edges_used[u]) == 0:
            continue
        edges_used[u] = set(sorted(edges_used[u]))
        for v in sorted(edges_used[u]):
            if G[u] & G[v]:
                continue
            for w in edges_used[u].difference({v}):
                new_edges.append(str(u) + ' ' + str(w))

    for i, edge in enumerate(new_edges):
        new_edges[i] = edge.replace(' ', '')

    return '\n'.join(new_edges)


