import sys

def min_operations(s, t):
    n, m = len(s), len(t)
    a, b = occur_in_bab(s), occur_in_bab(t)

    if a == 0 and b == 0:
        return 0
    elif a == 0 and b > 0:
        return 1
    elif a > 0 and b == 0:
        return 1

    if n < m:
        s, t = t, s
        a, b = b, a

    ans = []
    diff = a - b

    while a > b:
        a -= 1
        ans.append([1, a+1])

    while b > a:
        b -= 1
        ans.append([b+1, 1])

    if diff == -1:
        ans.append([m-b-m+1, m-b-b+1])

    if b - a > 2*m - diff - n:
        ans.append([2*m + 1, 2*m-1])

    if diff == 2*m - n + b:
        ans.append([m-1, m-1])

    if len(ans) > 0:
        max_length = max(idx for idx, op in enumerate(ans) for len_ in op)
        ans.sort(key=lambda x: x[0])
        ans[len(ans) - 1] = [(max_length + 1, max_length + 1)]
    return ans

def occur_in_bab(s):
    n = len(s)
    count_a = count_b = 0
    for i in range(n):
        if i and s[i] == 'a':
            count_a += 1
        if i and s[i-1] == 'b':
            count_b += 1
        if count_b > count_a:
            return count_b - count_a
    return count_b - count_a

if __name__ == "__main__":
    s = input().strip()
    t = input().strip()
    print(min_operations(s, t))
