def shake_tree(root_nodes, shake_times):
    n = len(root_nodes)
    edge_list = []
    for i in range(1, n):
        (parent, child) = (root_nodes[i-1], root_nodes[i])
        edge_list.append((parent, child))

    graph = build_graph(n, edge_list)
    raindrops = [1] + [0] * n

    for shake in shake_times:
        dropped_nodes = []
        for i in range(n):
            if raindrops[i]:
                dropped_nodes.append(i)
                raindrops[i] = 0
        for node in dropped_nodes:
            if node != root_nodes[0]:
                parent = (root_nodes[node-1] if node != 1 else root_nodes[1])
                if graph[parent]:
                    for child in graph[parent]:
                        if raindrops[child]:
                            raindrops[child] = 0
        for node in range(1, n+1):
            if raindrops[node-1]:
                raindrops[node] += 1
    return raindrops

