from collections import defaultdict

class NestedIterator:
    def __init__(self, arr):
        self.stack = [(len(arr) - 1, None)]
        self.index = 0

    def next(self):
        self.index += 1
        _, val = self.stack[-1]
        self._pop()
        return val

    def hasNext(self):
        if self.stack:
            return not (self.stack[-1][0] - self.index) == 0
        else:
            return False

    def _pop(self):
        while self.stack and self.stack[-1][0] <= self.index:
            _, val = self.stack.pop()
        if self.stack:
            self.stack[-1] = (self.stack[-1][0] - 1, val)

    def __repr__(self):
        return f'NestedIterator([{",".join(self.index_array)}])'

class Solution:
    def minimizeOperations(self, s: str, t: str) -> str:
        s_vals = defaultdict(lambda: 0)
        t_vals = defaultdict(lambda: 0)
        for char in s:
            s_vals[char] += 1
        for char in t:
            t_vals[char] += 1

        s_min = min(len(s_vals), len(t_vals))
        t_min = min(len(s_vals), len(t_vals))

        s_prefix_len = t_prefix_len = 0
        operations_count = 0

        while s_prefix_len < len(s) or t_prefix_len < len(t):
            if len(s) - s_prefix_len < len(t) - t_prefix_len:
                for k, v in s_vals.items():
                    if t_vals[k] > v:
                        return s_prefix_len + t_prefix_len

                    if t_vals[k] < v:
                        t_prefix_len += min(t_vals[k], v)

                    t_prefix_len += max(v - t_vals[k], 0)

                    s_prefix_len = min(s_prefix_len, (s_prefix_len // k) * k + v - t_vals[k])

                s_prefix_len += s_prefix_len % min(s_vals[s[s_prefix_len]]) or 1
                t_prefix_len += s_prefix_len
            else:
                for k, v in t_vals.items():
                    if s_vals[k] > v:
                        return s_prefix_len + t_prefix_len

                    if s_vals[k] < v:
                        s_prefix_len += min(s_vals[k], v)

                    s_prefix_len += max(v - s_vals[k], 0)

                    t_prefix_len = min(t_prefix_len, (t_prefix_len // k) * k + v - s_vals[k])

                t_prefix_len += t_prefix_len % min(t_vals[t[t_prefix_len]]) or 1
                s_prefix_len += t_prefix_len

            s_prefix_len += 1
            t_prefix_len += 1
            operations_count += 1

        return operations_count
