def minimize_operations(s, t):
    operations = 0
    a_count, b_count = 0, 0  # to track the count of A and B in s and t

    try:
        pos_s = s.index('a')
        pos_t = t.index('b')
    except ValueError:
        return operations

    while pos_s < len(s) and pos_t < len(t):
        if s[pos_s] == 'a':
            if a_count > b_count:
                # Swap t
                operations += a_count - b_count
                b_count += 1
                pos_t += a_count - b_count
            else:
                b_count += 1
                pos_s += 1
                pos_t += 1
        else:
            if b_count > a_count:
                # Swap s
                operations += b_count - a_count
                a_count += 1
                pos_s += b_count - a_count
            else:
                a_count += 1
                pos_s += 1

    return operations


