    n = int(input())
    string_lengths = set(map(len, input().strip().split()))

    if len(string_lengths) == 1:
        return (Fraction(1, 1)**n).numerator

    probabilities = []
    for length in string_lengths:
        queue = deque([[length, 0]])
        while queue:
            current_length, current_count = queue.popleft()
            if current_count == 1:
                probabilities.append(Fraction(current_length**2, (length - 1)**2).numerator)
            next_count = (current_count + 1) * (current_length - 1) + 1
            for count in range(next_count, min(current_length + 1, length)):
                queue.append([current_length + count, next_count])
        probabilities[-1] = (probabilities[-1] + 1) / 9

    return sum(Fraction(1, length) for length in string_lengths) * sum(probabilities)

