import sys

def find_min_gas_tank(n, m, city_positions, truck_data):
    distances = [city_positions[i] - city_positions[0] for i in range(n)]
    truck_towns = {}
    for s, f, c, r in truck_data:
        if f not in truck_towns:
            truck_towns[f] = []
        truck_towns[f].append((s, c, r))

    @lru_cache(None)
    def dfs(current, remaining_tank, refuels):
        if remaining_tank < 0:
            return sys.maxsize
        if current == n:
            return 0
        min_tank = sys.maxsize
        for s, c, r in truck_towns[current]:
            if remaining_tank - (c * distances[s]) > 0:
                prev_min_tank = dfs(s, remaining_tank - (c * distances[s]), r)
                min_tank = min(min_tank, prev_min_tank + max(0, distances[s] - remaining_tank) * c)
        return min_tank

    return min(dfs(i, V, max(V - n, 0)) for i, V in enumerate(city_positions))

