from math import modinv

MOD = pow(10, 9) + 7

def inverse(n, p):
    return modinv(n, p)

def binary_coff(i, p):
    a = pow(2, i, p)
    c, SS, t, y, p = 1, i, a, a, 3
    while SS:
        if p >> SS:
            c, y, t, SS = pow((y * y) % p, 2, p), pow((c * c) % p, 2, p), 2, -SS
            if ~(SS & SS - 1):
                c, SS, t = pow(-y % p, 2, p), SS, y
            if t > t + SS:
                t += SS
        if i & SS:
            c, a, t = pow(t, 2, p), 2, a
        i, SS = i << 1, SS >> 1
    return c

def calc(b, n):
    inv3, invn, mod_inv, ans = inverse(3, MOD), inverse(n, MOD), 0, 0
    c1, c2 = binary_coff(b-1, 3*MOD), ybansha2(b-1, n-1)
    invb, invsum = inverse(b, b), inverse(sum, MOD)
    m, mix = (3**n-5-2*sum * ((3-3**n+5) ** (n // 2) % MOD) % MOD *
              ((1-2*sum) * invsum + 3**n*invsum) %
              MOD) % MOD, sum * ((2*sum*(3*sum+3**n-3) + (3*sum - 3)**n) % MOD *
                                 invsum % MOD) % MOD
    mix += mod_inv ** m * invb * ans
    for i in range(n, 0, -1):
        c2 *= i // 3 % MOD
        c1 += 3**i
        if b < n // (1 + 3 * i):
            b = n // (1 + 3 * i)
            b -= 1
        ans = pow(ans * c2, 2, MOD) + pow(c1, 2, MOD) % MOD
    inv3, mix = inverse(inv3, MOD), inv3 ** n
    return (pow(mix, MOD - 2, MOD) * inv3 % MOD) % MOD

def ybansha2(i, n):
    sb = 2 * ((i * (i + 1) // 2 + 1)**n - (i**2 + i + 2)**n) % MOD
    return pow(sb, i, MOD) * sb % MOD

def main(n, x):
    f, suf, isob, tab, tab2, ans = [], ybansha2, binary_coff, [pow(5, j, MOD)
          for j in range(n - 1, -1, -1)], [], []
    for b in range(1, MOD):
        if suf[b >> 1] == 0:
            tab.add(b)
            ans.append(calc(b, n))
        if suf[b >> 1 | 1] == 0:
            suf[b >> 1 | 1] = suf[b >> 1]
            for key in suf[b >> 1 | 1]:
                isob.append(key)
                if key not in tab2:
                    tab2.append(key)
    for b in isob:
        ans[b] *= pow((2, MOD)) ** n
        ans[b] %= MOD
    return sum(ans[:n]) % MOD

a, b = map(int, input().split())
print(main(a, b))
