def build_treap(data):
    # Treap operations
    size = 1
    def insert(root, value):
        if not root:
            return TreeNode(size, value)
        size += 1
        if value <= root.value:
            root.left = insert(root.left, value)
        else:
            root.right = insert(root.right, value)
        return root
    def find(value):
        return find_node(root, value)
    def find_node(root, value):
        if not root:
            return None
        if root.value == value:
            return root
        elif value <= root.value:
            return find_node(root.left, value)
        else:
            return find_node(root.right, value)
    def __merge(left, right):
        if not left:
            return right
        if not right:
            return left
        if left.value > right.value:
            return TreeNode(max(list[left].size + list[right].size), left.value, __merge(left.left, right), __merge(left.right, right.right))
        else:
            return TreeNode(max(list[left].size + list[right].size), right.value, __merge(left, right.left), __merge(left, right.right))
    def rotate_right(root):
        new_root, left, right = root, root.left, root.right
