import math

class patience_tap:
    def __init__(self, initial_p, drain_rate, par_time=-math.inf):
        self.p = initial_p
        self.d = drain_rate
        self.par_time = par_time

    def simulate(self):
        while self.p > 0:
            self.p += self.d
        return self.par_time

    def update_par_time(self, t):
        self.par_time = t

    def update_pat(self, new_p):
        self.p = new_p

    def update_drain(self, s):
        self.d = s

    def burst_time(self, l, r, v):
        if v <= 0:
            return -1 if self.p <= 0 else float('inf')
        if self.p <= 0:
            return r + 1 if l <= r <= self.par_time else float('inf')
        max_par_time = min(t for t in range(l + math.ceil(math.log((self.p * r + 1) / (self.d * l))),))
        if self.p <= 0:
            return max_par_time if self.p <= 0 else float('inf')
        min_drain_rate = (self.p * r - self.d * (r - l)) / (r - math.floor(math.log((self.p * r + 1) / (self.d * l)))))
        if self.p <= 0:
            return float('inf') if min_drain_rate <= 0 else -1
        leaves_num = (self.d * (r - l) * (1 - min_drain_rate) + (self.p - self.d * (r - l)) * l + max_par_time) / (self.p * r - self.p * l) + 1
        if l <= r <= self.par_time:
            time = max_par_time
        else:
            time = max_par_time if leaves_num % 2 else r + 1
        return time if l <= r <= self.par_time else float('inf') if leaves_num <= 0 else -1

