def combine(T, i, count):
    components = {}
    for j in range(T):
        if (i & (1 << j)) == 0:
            continue
        c = components.setdefault(T[j], 0)
        T[j] = c + 1
        count[c] -= 1
        for k in range(T):
            if (i & (1 << k)) > 0:
                count[components[(i & (1 << k))]] += 1
    return T, count

def dfs(T1, T2, count1, count2):
    T = []
    for i in range(len(T1)):
        if T1[i] > 1:
            T.append(T1[i])
            T1[i] = 1
        if T1[i] > 0:
            T1[i] -= 1
            T2[i] += 1
            count2[(T[i] << len(T2)) | T2[i]] += 1
    count = T1[:]
    T, count1 = combine(count1, T1, count)
    T2, count2 = combine(count2, T2, count)
    for i in range(len(T1)):
        if T1[i] == 0:
            T[i] = T1[i - 1] - 1 if i - 1 >= 0 else 0
            del T1[i - 1]
            T1[i] += 1
    for i in range(len(T2)):
        if T2[i] == 0:
            T2[i] = T2[i - 1] - 1 if i - 1 >= 0 else 0
            del T2[i - 1]
            T2[i] += 1
    return T, count1, count2

def getf(T, count1):
