    def calc(A, B):
        res = [0] * (len(T) + 1)
        for i in range(len(T)):
            res[i + max(A, B) + A * (T[i] == 0)] += count[i]
        return res

    def ok():
        T, count1 = dfs(count1, T, count, count)
        T, count2 = dfs(T, count1, count, count)
        return count2 and ok() and calc(count, count1) == calc(count, count2)

    f = [0]
    count[0] = 1
    while count:
        T = sorted(f[-1] + 1)
        if ok():
            break
        f.append(T)
