    dp = [[0] * k for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(k):
            dp[i][j] = sum(dp[i - 1][k - 1 - x]) % MOD
            if j >= 1:
                dp[i][j] = (dp[i][j] + MOD - dp[i - 1][j - 1]) % MOD
            if j < k - 1:
                dp[i][j] = (dp[i][j] + MOD - dp[i - 1][k - 1 - (j + 1)]) % MOD
    return (dp[n][k-1] + MOD) % MOD

