def minimize_operations(s, t):
    operations = []

    a_count, b_count = 0, 0
    min_len_b = float('inf')
    max_len_b = float('-inf')
    min_len_a = float('inf')
    max_len_a = float('-inf')

    for i, char in enumerate(s):
        if char == 'a':
            a_count += 1
        else:
            b_count += 1
            if a_count < b_count:
                min_len_b = min(min_len_b, i + 1)
            else:
                max_len_b = max(max_len_b, i + 1)

    for i, char in enumerate(t):
        if char == 'a':
            a_count += 1
        else:
            b_count += 1
            if a_count >= b_count:
                min_len_a = min(min_len_a, i + 1)
            else:
                max_len_a = max(max_len_a, i + 1)

    if a_count < b_count:
        min_len_b = min(min_len_b, 0)
    else:
        max_len_b = max(max_len_b, 0)

    if a_count >= b_count:
        min_len_a = min(min_len_a, 0)
    else:
        max_len_a = max(max_len_a, 0)

    operations.append((min_len_a, max_len_a))
    operations.append((min_len_b, max_len_b))

    return len(operations), operations

# Example usage
